  'chat.designToolbox.context.file': 'Fichier',
  'chat.designToolbox.prompt.contextGeneric': 'Cible actuelle : le fichier HTML / de conception ou l\'élément web actuellement ouvert.',
  'chat.designToolbox.prompt.contextSpecific': 'Cible actuelle : {kind} · {label}.',
  'chat.designToolbox.prompt.preserveDraft': 'Préservez l\'intention déjà présente dans le composeur : {draft}',
  'chat.designToolbox.prompt.selectedSkill': 'Skill sélectionné : {skill}. Utilisez-le comme flux de travail principal pour ce tour.',
  'chat.designToolbox.prompt.noSkill': 'Si aucun skill spécifique ne correspond, choisissez d\'abord la meilleure combinaison parmi les skills, MCP, plugins, connecteurs et fichiers de conception disponibles.',
  'chat.designToolbox.prompt.autoMatchIntro': 'Agissez en tant qu\'orchestrateur Directeur Créatif et menez à bien un flux de travail de conception :',
  'chat.designToolbox.prompt.autoMatchStep1': '1. Définissez d\'abord ce que signifie « un design réussi » : audience, objectif commercial, identité de marque, références de style, densité d\'information, normes de couleur/typographie/animation/ressources, et motifs IA/modèles à éviter.',
  'chat.designToolbox.prompt.autoMatchStep2': '2. Recherchez et associez l\'ensemble de l\'index des ressources ci-dessus. Ne vous limitez pas aux recommandations de la boîte à outils de conception ; combinez skills, MCP, plugins, connecteurs et fichiers de conception lorsque c\'est utile.',
  'chat.designToolbox.prompt.autoMatchStep3': '3. Si la cible ou le niveau d\'exigence esthétique reste flou, guidez-moi avec des choix limités ou une interface de type formulaire et incluez une valeur par défaut recommandée. Si c\'est suffisamment clair, exécutez directement l\'étape suivante.',
  'chat.designToolbox.prompt.autoMatchStep4': '4. Menez le flux dans cet ordre : diagnostic -> direction stylistique -> sélection des ressources -> édition/génération concrète -> vérification. À chaque étape, expliquez pourquoi ces ressources ont été choisies et ce qui doit être confirmé ensuite.',
  'chat.designToolbox.prompt.motion': 'Ajoutez une animation de haute qualité à l\'élément HTML / de page actuel : choisissez les 1 à 2 moments d\'entrée, de défilement, de transition d\'état ou de micro-interaction les plus utiles. Restez sobre, privilégiez transform / opacity et incluez des solutions de repli prefers-reduced-motion.',
  'chat.designToolbox.prompt.motionPolish': 'Examinez et peaufinez la synchronisation, l\'accélération, les performances et l\'accessibilité des animations existantes. Supprimez les animations abruptes, bas de gamme ou nuisant à la lisibilité ; utilisez une chronologie plus raffinée si nécessaire.',
  'chat.designToolbox.prompt.antiAiPolish': 'Effectuez une passe de finition anti-effet-IA : supprimez les mises en page standardisées, les dégradés/halos bas de gamme, les empilements de cartes dénués de sens et les textes vagues. Préservez l\'information et donnez l\'impression qu\'un vrai designer l\'a livrée.',
  'chat.designToolbox.prompt.visualPolish': 'Peaufinez ce design jusqu\'à ce qu\'il soit prêt à être livré : vérifiez la hiérarchie, la typographie, les espacements, le comportement responsive, les états des boutons, les états vide/chargement/erreur et l\'accessibilité ; corrigez directement les problèmes les plus importants.',
  'chat.designToolbox.prompt.imageGen': 'Créez le prochain plan de ressources visuelles pour ce design : références de section, visuels hero, illustrations, icônes, images pour les réseaux sociaux ou un moodboard. Décidez d\'abord quel type d\'image manque, puis fournissez des prompts de génération exécutables / un plan de fichiers.',
  'chat.designToolbox.prompt.videoGen': 'Orientez ce design vers la vidéo : créez un storyboard de vidéo courte, une structure de frames Hyperframes / Remotion, ou un prompt prêt pour Sora/fal. Privilégiez le fait de transformer naturellement le contenu HTML / de la page existant en plans.',
  'chat.designToolbox.prompt.useSkill': 'Utilisez {skill} sur le design actuel.',
  'chat.designToolbox.prompt.skillInstruction': 'Décidez d\'abord du meilleur objectif de suivi, puis réalisez une passe concrète. Si cela dépend de ressources ou d\'API externes, fournissez une solution de repli exécutable ou indiquez ce que je dois fournir.',
  'chat.designToolbox.prompt.selectedResource': 'Ressource sélectionnée : {kind} · {title} ({id}).',
  'chat.designToolbox.prompt.resourceDescription': 'Description de la ressource : {description}',
  'chat.designToolbox.prompt.pluginResource': 'Utilisez ce plugin comme contexte principal pour le flux de design actuel. S\'il expose des entrées ou une GenUI, guidez-moi pour choisir le moment venu ; s\'il ne convient pas à la cible, choisissez une meilleure ressource globale et expliquez pourquoi.',
  'chat.designToolbox.prompt.mcpResource': 'Privilégiez cette capacité MCP pour la prochaine étape de design. Lorsque des ressources externes, une capture web, une génération d\'image/vidéo ou des données sont nécessaires, décidez d\'abord s\'il peut faire le travail, puis proposez un plan exécutable.',
  'chat.designToolbox.prompt.mcpTemplateResource': 'Ce MCP est un modèle configurable. S\'il s\'agit de l\'outil le plus utile pour cette étape de design, guidez d\'abord la configuration ; si une alternative configurée existe, poursuivez avec cette alternative.',
  'chat.designToolbox.prompt.connectorResource': 'Utilisez ce connecteur lorsque des données réelles, des ressources, du contenu de compte ou un accès à un workflow externe sont nécessaires. Avant de l\'utiliser, expliquez ce qui sera lu ou écrit et demandez confirmation le cas échéant.',
  'chat.designToolbox.prompt.fileResource': 'Utilisez ce fichier de design comme cible de design actuelle ou ressource de référence et réalisez l\'étape suivante à partir de celui-ci. Si d\'autres fichiers nécessitent une comparaison, poursuivez la recherche dans tous les fichiers de design.',
  'chat.designToolbox.prompt.resourceIndex': 'Index des ressources globales : skills({skills}), plugins({plugins}), MCP({mcpEnabled} activés / {mcpTemplates} modèles), connecteurs({connectors} connectés), fichiers de design({files}).',
