  // Pixflow interface copy.
  "wp.message.26a6374fbf59": "Une extension Pixflow n’a pas pu démarrer. Vérifiez la compatibilité de vos extensions Pixflow, puis rechargez. D’autres fonctionnalités peuvent rester disponibles.",
  "wp.message.ca7714cffbcc": "Activer Pro",
  "wp.message.197c83a2f752": "Retrouvez vos outils premium avec l’extension Pro. Votre licence, votre contenu et vos paramètres enregistrés sont conservés. Si vous utilisiez l’authentification à deux facteurs de Bricks, réactivez-la dans les paramètres après l’activation de Pro.",
