  "ui.finalOnboarding.28edc3b8f2": "Connectez votre abonnement IA",
  "ui.finalOnboarding.f9573d1164": "Vous êtes prêt à créer",
  "ui.finalOnboarding.45ddd1221b": "L’édition WordPress et Gutenberg est gratuite. Aucune licence ni période d’essai n’est nécessaire.",
