  "ui.mediaStarter.image1.title": "Portrait éditorial",
  "ui.mediaStarter.image1.tag": "Portrait",
  "ui.mediaStarter.image1.prompt": "Portrait éditorial en gros plan d’un jeune directeur artistique d’environ 28 ans, lumière naturelle douce à travers de hautes fenêtres d’atelier, palette neutre chaude (crème, taupe, noir doux), prise au 85 mm f/1.8 avec faible profondeur de champ, regard vif directement vers l’objectif, grain argentique subtil, apparence sans maquillage.",
  "ui.mediaStarter.image2.title": "Visuel principal de produit",
  "ui.mediaStarter.image2.tag": "Commerce en ligne",
  "ui.mediaStarter.image2.prompt": "Une photo principale haut de gamme d’une seule tasse à café en céramique mate sur un fond de papier crème chaud. Éclairage de contour dur en haut à gauche, ombre douce allongée vers le bas à droite, légère vapeur au-dessus de la tasse. Cadrage carré, composition centrée, espace en haut pour un titre, aucun accessoire ni main dans le cadre.",
  "ui.mediaStarter.image3.title": "Illustration à plat",
  "ui.mediaStarter.image3.tag": "Illustration",
  "ui.mediaStarter.image3.prompt": "Illustration vectorielle à plat d’un coin lecture douillet près d’une fenêtre sous la pluie : formes géométriques, palette sobre de cinq couleurs (crème, terre cuite, bleu canard foncé, terre de Sienne brûlée, noir doux), fins traits de 1.5px, sans dégradés ni textures, ombres douces uniquement sous le fauteuil au premier plan.",
  "ui.mediaStarter.video1.title": "Révélation de produit",
  "ui.mediaStarter.video1.tag": "Cinématographique",
  "ui.mediaStarter.video1.prompt": "Une révélation de produit de 5 secondes : flacon minimaliste de soin haut de gamme sur une surface de pierre crème épurée, lumière latérale douce à gauche de la caméra, lent rapprochement, déplacement subtil de la mise au point du bouchon vers l’étiquette, mouvement sobre, aucun texte superposé ni personne dans le cadre.",
  "ui.mediaStarter.video2.title": "Lanterne en gros plan",
  "ui.mediaStarter.video2.tag": "Ambiance",
  "ui.mediaStarter.video2.prompt": "Un gros plan cinématographique de 6 secondes sur une jeune femme tenant une lanterne en papier lumineuse dans une pinède brumeuse à l’heure dorée. Faible profondeur de champ sur les yeux, travelling avant doux, particules flottant dans un rayon chaud, aucun dialogue, seulement les sons de la forêt.",
  "ui.mediaStarter.video3.title": "Drift dans une rue néon",
  "ui.mediaStarter.video3.tag": "Action",
  "ui.mediaStarter.video3.prompt": "Un travelling de course urbaine de 5 secondes, la nuit, dans une ruelle cyberpunk de Hong Kong éclairée au néon. Caméra basse suivant une voiture de sport noire mate en drift dans un virage serré, roues floues par le mouvement, reflets optiques des enseignes néon, asphalte mouillé reflétant les lumières, aucun texte à l’écran.",
  "ui.mediaStarter.hyperframes1.title": "Révélation à la loupe",
  "ui.mediaStarter.hyperframes1.tag": "HTML-in-canvas",
  "ui.mediaStarter.hyperframes1.prompt": "Crée une composition de 5 secondes avec une seule ligne de texte de titrage en gras sur un fond épuré. Anime une loupe ronde se déplaçant de gauche à droite sur la ligne, avec une réfraction subtile déformant les lettres au passage. Utilise HyperFrames html-in-canvas : capture le DOM du texte et superpose un shader de lentille avec une passe de type vfx-liquid-glass. Texte en CSS pur ; verre sur une couche WebGL.",
  "ui.mediaStarter.hyperframes2.title": "Scène de terminal CRT",
  "ui.mediaStarter.hyperframes2.tag": "Effets rétro",
  "ui.mediaStarter.hyperframes2.prompt": "Crée une composition d’écran CRT : fond sombre, texte de terminal monospace tapant `npx hyperframes init my-video`, puis appel de `claude` avec la demande « Ajoute un effet CRT avec HTML-in-canvas ». Applique une légère courbure convexe, des lignes de balayage, une faible aberration chromatique et une lueur phosphorescente douce sur le DOM actif via html-in-canvas. Le texte reste en vrai CSS pour être net avant le shader.",
  "ui.mediaStarter.hyperframes3.title": "Décomposition glitch",
  "ui.mediaStarter.hyperframes3.tag": "Glitch",
  "ui.mediaStarter.hyperframes3.prompt": "Crée une composition de 6 secondes affichant un grand titre et un sous-titre d’une ligne sur fond sombre, puis une rupture numérique marquée : séparation RGB, bandes de décalage horizontal, bref bégaiement d’images et retour final net. Capture le DOM actif via html-in-canvas et superpose l’effet glitch, afin que la typographie reste du vrai CSS sous le shader.",
  "ui.mediaStarter.audio1.title": "Voix off de marque",
  "ui.mediaStarter.audio1.tag": "Parole",
  "ui.mediaStarter.audio1.prompt": "Une voix off narrative chaleureuse de 30 secondes pour une vidéo de lancement : assurée mais naturelle, rythme moyen, légère pause après le nom de marque. Texte : 'Three years in the making. One simple promise. Meet [product name] — the way work was supposed to feel.' En anglais, accent nord-américain neutre.",
  "ui.mediaStarter.audio2.title": "Narration d’accueil",
  "ui.mediaStarter.audio2.tag": "Parole",
  "ui.mediaStarter.audio2.prompt": "Une narration d’accueil amicale de 20 secondes pour le premier lancement d’une application mobile. Ton rassurant et souriant, assez lent pour être attentionné sans sembler récité. Texte : « Bienvenue dans Loop. Installons votre espace : trois petites questions et c’est parti. Vous pourrez tout modifier plus tard. »",
  "ui.mediaStarter.audio3.title": "Lecture d’un récit",
  "ui.mediaStarter.audio3.tag": "Parole",
  "ui.mediaStarter.audio3.prompt": "Une lecture cinématographique de 45 secondes d’un passage d’ouverture. Voix basse et mesurée, respirations entre les phrases, intimité d’un micro proche. Texte : « La ville dort par fragments. Une enseigne néon clignote au-dessus du comptoir à ramen. De l’autre côté de l’avenue, une fenêtre brille : la seule encore allumée de ce côté de minuit. »",
